CREATE SCHEMA IF NOT EXISTS bronze;
CREATE TABLE IF NOT EXISTS bronze.nuxeo_eventos (
    id BIGSERIAL PRIMARY KEY,
    placa VARCHAR(20)
);

SELECT DISTINCT UPPER(TRIM(placa)) AS placa FROM bronze.nuxeo_eventos WHERE placa IS NOT NULL AND placa <> '';

