const response = $('02 - Buscar Frota Nuxeo API').first().json;
const token = $('01 - Nuxeo Auth').first().json.token;
const listaNuxeo = response.positions || response.targets || response || [];

// Obter lista de placas ja gravadas na tabela bronze.nuxeo_eventos
const jaProcessadasItems = $input.all();
const jaProcessadasSet = new Set();
for (const item of jaProcessadasItems) {
  if (item.json && item.json.placa) {
    jaProcessadasSet.add(String(item.json.placa).trim().toUpperCase());
  }
}

const pendentes = [];
const placasVistas = new Set();

for (const v of listaNuxeo) {
  const placa = (v.identifier || '').trim().toUpperCase();
  if (!placa || placasVistas.has(placa)) continue;
  placasVistas.add(placa);

  // Se a placa ja foi salva no DW, pula para nao duplicar trabalho
  if (jaProcessadasSet.has(placa)) {
    console.log(`[SKIP] Placa ${placa} ja foi processada anteriormente.`);
    continue;
  }

  pendentes.push({
    json: {
      token,
      placa
    }
  });
}

console.log(`[BACKFILL RESUMABLE] Total Nuxeo: ${listaNuxeo.length} | Já no Banco: ${jaProcessadasSet.size} | Pendentes a processar: ${pendentes.length}`);
return pendentes;

const item = $input.first().json;
const token = item.token;
const placa = item.placa;

if (!placa) {
  return [{ json: { _skip: true } }];
}

// Janelas Mensais de 01/01/2026 ate hoje
const janelas = [
  { begin: '01/01/2026 00:00:00', end: '31/01/2026 23:59:59' },
  { begin: '01/02/2026 00:00:00', end: '28/02/2026 23:59:59' },
  { begin: '01/03/2026 00:00:00', end: '31/03/2026 23:59:59' },
  { begin: '01/04/2026 00:00:00', end: '30/04/2026 23:59:59' },
  { begin: '01/05/2026 00:00:00', end: '31/05/2026 23:59:59' },
  { begin: '01/06/2026 00:00:00', end: '30/06/2026 23:59:59' },
  { begin: '01/07/2026 00:00:00', end: '31/07/2026 23:59:59' }
];

const requests = [];
for (const j of janelas) {
  const beginEnc = encodeURIComponent(j.begin);
  const endEnc = encodeURIComponent(j.end);
  requests.push({
    json: {
      token,
      placa,
      begin: j.begin,
      end: j.end,
      url: `https://api.nuxeo.com.br/rest/report/events/?begin=${beginEnc}&end=${endEnc}&plate=${placa}`
    }
  });
}

console.log(`[BACKFILL RESUMABLE] Processando Placa Pendente: ${placa}`);
return requests;

const rawItems = $input.all();

const esc = (v) => v != null ? String(v).replace(/'/g, "''") : null;
const valStr = (v) => v != null ? `'${esc(v)}'` : 'NULL';
const valNum = (v) => (v != null && !isNaN(v)) ? Number(v) : 'NULL';
const valJson = (obj) => `'${JSON.stringify(obj).replace(/'/g, "''")}'::jsonb`;

const sqlStatements = [];
sqlStatements.push(`
CREATE SCHEMA IF NOT EXISTS bronze;
CREATE TABLE IF NOT EXISTS bronze.nuxeo_eventos (
    id BIGSERIAL PRIMARY KEY,
    placa VARCHAR(20),
    complemento TEXT,
    nome_evento TEXT,
    data_evento TEXT,
    velocidade NUMERIC(6,2),
    latitude NUMERIC(10,6),
    longitude NUMERIC(10,6),
    endereco TEXT,
    cidade VARCHAR(150),
    estado VARCHAR(50),
    pais VARCHAR(50),
    payload_json JSONB,
    ingested_at TIMESTAMPTZ DEFAULT NOW()
);
`);

let totalRecords = 0;
const allEvents = [];

for (const item of rawItems) {
  const resp = item.json;
  if (resp._skip) continue;
  const events = resp.events || [];
  if (!Array.isArray(events) || events.length === 0) continue;
  for (const evt of events) {
    allEvents.push({
      ...evt,
      placaFallback: resp.placa
    });
  }
}

if (allEvents.length === 0) {
  return [{ json: { _sql: "SELECT 0 AS inseridos;", totalRecords: 0 } }];
}

const chunkSize = 500;
for (let i = 0; i < allEvents.length; i += chunkSize) {
  const chunk = allEvents.slice(i, i + chunkSize);
  const values = chunk.map(evt => {
    totalRecords++;
    const placaFinal = evt.identifier || evt.placaFallback;
    return '('
      + valStr(placaFinal) + ', '
      + valStr(evt.complement) + ', '
      + valStr(evt.event) + ', '
      + valStr(evt.date) + ', '
      + valNum(evt.speed) + ', '
      + valNum(evt.latitude) + ', '
      + valNum(evt.longitude) + ', '
      + valStr(evt.address) + ', '
      + valStr(evt.city) + ', '
      + valStr(evt.state) + ', '
      + valStr(evt.country) + ', '
      + valJson(evt)
      + ')';
  }).join(',\n');

  sqlStatements.push(`
    INSERT INTO bronze.nuxeo_eventos (
      placa, complemento, nome_evento, data_evento, velocidade, latitude, longitude, endereco, cidade, estado, pais, payload_json
    ) VALUES ${values};
  `);
}

return [{ json: { _sql: sqlStatements.join('\n'), totalRecords } }];
